\title[The Master Table of Splitting-Type Channels]{The Master Table of Splitting-Type Channels for Cyclic and Dihedral Galois Groups of Degree 3 to 6, and the General Laws Behind It}
\author{Aristotle (Harmonic)}
\date{September 29, 2026}

\begin{document}

\begin{abstract}
For a Galois extension $K/\mathbb{Q}$ with group $G$, the Chebotarev density theorem makes the Frobenius class of a random prime a uniformly distributed element of $G$. The splitting type of the prime is then a random variable, and we can measure its Shannon entropy and its mutual information with various coarse read-outs. We give closed forms for all six measured channels (cyclic type, cyclic root count, the semiprime pair channel, dihedral type, the dihedral non-abelian residue, and the rotation dial) for the cyclic groups $C_n$ and the dihedral groups $D_n$ with $n\in\{3,4,5,6\}$. We then show that every cyclic root-count and dihedral entry is a special case of a law valid for all degrees. (i) The cyclic root-count entropy equals the pinning entropy $\pi(n)=h(1/n)$ for every $n$, and it equals the full type entropy if and only if $n$ is prime. (ii) The dihedral type entropy is $1+\pi(n)/2$ for odd $n$, and has an explicit closed form for even $n$. (iii) The rotation fibre of $D_n$ is precisely the cyclic root-count channel. (iv) For $n\ge 3$, the rotation character carries exactly one bit about the dihedral type if and only if $n$ is odd. The proof uses a chain rule for counting entropy and the symmetry of mutual information. (v) $\pi(n)\to 0$, so along odd degrees the abelian share of dihedral type information tends to $1$, although the non-abelian residue is strictly positive at every finite degree.
\end{abstract}

\maketitle

\section{Introduction}

Let $f\in\Z[x]$ be monic and irreducible of degree $n$, with splitting field $K$ and Galois group $G$ acting on the $n$ roots. For a prime $p$ unramified in $K$, the factorisation pattern of $f\bmod p$ is the cycle type of the Frobenius class $\mathrm{Frob}_p$ acting on the roots. In particular, the number of roots of $f$ in $\mathbb{F}_p$ equals the number of roots fixed by $\mathrm{Frob}_p$. By the Chebotarev density theorem, the density of primes whose Frobenius lies in a conjugacy class $C$ is $|C|/|G|$. Every statistical question about splitting types of random primes therefore reduces to a question about a uniformly random element of $G$.

We treat the two basic families of Galois groups: cyclic fields of degree $n$ (group $C_n$ acting regularly), and dihedral radical fields such as $x^n-a$ (group $D_n$ acting on the roots as on the vertices of a regular $n$-gon). The first contribution is a master table with every channel value in degrees $3$ to $6$ in closed form (Section~\ref{sec:table}). The main contribution is that the table is explained: each cyclic root-count and dihedral column is an instance of a law valid for all $n$ (Sections~\ref{sec:cyclic}--\ref{sec:parity}), proved by structural arguments rather than enumeration.

\section{Counting entropy}

\begin{definition}[Counting entropy]
Let $s$ be a finite nonempty set and $g\colon s\to B$. The entropy of $g$ on $s$ is
\[
H_s(g)=\log_2|s|-\frac{1}{|s|}\sum_{a\in s}\log_2\bigl|\{x\in s: g(x)=g(a)\}\bigr|,
\]
which is the Shannon entropy of $g(X)$ for $X$ uniform on $s$.
\end{definition}

\begin{definition}[Conditional entropy, mutual information]
For $g\colon s\to B$ and $k\colon s\to C$,
\[
H_s(g\mid k)=\sum_{c\in k(s)}\frac{|k^{-1}(c)|}{|s|}H_{k^{-1}(c)}(g),\qquad I_s(g;k)=H_s(g)-H_s(g\mid k).
\]
\end{definition}

\begin{definition}[Pinning entropy]
For $N\ge1$, $\pi(N)=\log_2N-\frac{N-1}{N}\log_2(N-1)$ (with $0\log_20=0$). Equivalently $\pi(N)=h(1/N)$, where $h(t)=-t\log_2t-(1-t)\log_2(1-t)$.
\end{definition}

With $L=\log_23$ and $L_5=\log_25$ one has
$\pi(3)=L-\tfrac23$, $\pi(4)=2-\tfrac34L$, $\pi(5)=L_5-\tfrac85$, $\pi(6)=1+L-\tfrac56L_5$.

\begin{lemma}[Uniform fibres]\label{lem:uniform}
If every fibre of $g$ on $s$ has exactly $c$ elements, then $H_s(g)=\log_2|s|-\log_2c$. In particular a constant read-out has entropy $0$.
\end{lemma}
\begin{proof}
Every summand equals $\log_2c$.
\end{proof}

\begin{lemma}[Pinned read-out]\label{lem:pinned}
If $a_0\in s$, $g(x)=g(a_0)$ implies $x=a_0$, and $g$ is constant on $s\setminus\{a_0\}$, then $H_s(g)=\pi(|s|)$.
\end{lemma}
\begin{proof}
The fibres are $\{a_0\}$ and $s\setminus\{a_0\}$, so the sum equals $(|s|-1)\log_2(|s|-1)$.
\end{proof}

\begin{theorem}[Chain rule for a determined dial]\label{thm:chain}
For $g\colon s\to B$ and $\varphi\colon B\to C$,
$H_s(g)=H_s(\varphi\circ g)+H_s(g\mid\varphi\circ g)$. Consequently $I_s(g;\varphi\circ g)=H_s(\varphi\circ g)$.
\end{theorem}
\begin{proof}[Proof sketch]
Put $k=\varphi\circ g$. Inside a $k$-fibre $F$, the $g$-fibre of a point is its global $g$-fibre. Expanding $\frac{|F|}{|s|}H_F(g)$ and summing over $F$, the first terms reassemble to $\log_2|s|-H_s(k)$ and the second to $\log_2|s|-H_s(g)$.
\end{proof}

\begin{lemma}[Fibrewise congruence]\label{lem:congr}
If on every fibre of $k$ the read-outs $g,g'$ induce the same partition, then $H_s(g\mid k)=H_s(g'\mid k)$.
\end{lemma}

\begin{theorem}[Symmetry of mutual information]\label{thm:symm}
$I_s(g;k)=I_s(k;g)$. Hence $I_s(g;k)\le H_s(k)$.
\end{theorem}
\begin{proof}[Proof sketch]
Apply Theorem~\ref{thm:chain} to $P=(g,k)$ with both projections, getting $H_s(P)=H_s(g)+H_s(P\mid g)=H_s(k)+H_s(P\mid k)$. Lemma~\ref{lem:congr} identifies $H_s(P\mid g)=H_s(k\mid g)$ and $H_s(P\mid k)=H_s(g\mid k)$. Rearrange.
\end{proof}

\begin{lemma}[Strict positivity]\label{lem:pos}
If $g$ is non-constant on $s$ then $H_s(g)>0$. If a fibre of $k$ contains two points with different $g$-values then $H_s(g\mid k)>0$.
\end{lemma}

\section{The channels}

\subsection*{Cyclic}
Frobenius is a uniform $a\in\Z/n$. Its type is its order $T(a)=n/\gcd(a,n)$, and its root count is $R(a)=n$ if $T(a)=1$ and $0$ otherwise (the action is regular). Put $H^C(n)=H_{\Z/n}(T)$ and $R^C(n)=H_{\Z/n}(R)$. The semiprime pair channel is
\[
\Ipair(n)=I\bigl((T(a),T(b));T(a+b)\bigr),\qquad (a,b)\text{ uniform on }(\Z/n)^2,
\]
the information the splitting types of two primes $p,q$ carry about the type of the product class.

\subsection*{Dihedral}
$D_n=\{r_i,s_i\}$ acts on $v\in\Z/n$ by $r_i(v)=v+i$ and $s_i(v)=i-v$. The type is $T(g)=\#\{v:g(v)=v\}$, the number of roots of $x^n-a$ modulo $p$. The rotation dial is $\rho(r_i)=0$, $\rho(s_i)=1$. Put $H^D(n)=H_{D_n}(T)$, $\Res(n)=H_{D_n}(T\mid\rho)$ and $\Dial(n)=I_{D_n}(T;\rho)$.

\section{The master table}\label{sec:table}

\begin{theorem}[Master table]
With $L=\log_23$ and $L_5=\log_25$:
\[
\renewcommand{\arraystretch}{1.5}
\begin{array}{c|cccccc}
n & H^C & R^C & \Ipair & H^D & \Res & \Dial\\\hline
3 & L-\frac23 & L-\frac23 & L-\frac{10}9 & \frac23+\frac L2 & \frac L2-\frac13 & 1\\
4 & \frac32 & 2-\frac{3L}4 & \frac54 & \frac{11}4-\frac{5L_5}8 & \frac32-\frac{3L}8 & \frac54+\frac{3L}8-\frac{5L_5}8\\
5 & L_5-\frac85 & L_5-\frac85 & L_5+\frac{12L}{25}-\frac{72}{25} & \frac15+\frac{L_5}2 & \frac{L_5}2-\frac45 & 1\\
6 & \frac13+L & 1+L-\frac{5L_5}6 & L-\frac19 & \frac{3L}4 & 1+\frac L2-\frac{5L_5}{12} & \frac L4+\frac{5L_5}{12}-1
\end{array}
\]
\end{theorem}
\begin{proof}
Column 1 is the order distribution of $\Z/n$. Column 3 is a finite evaluation over $n^2$ pairs. Columns 2, 4, 5 and 6 are specialisations of Theorems~\ref{thm:rootcount}, \ref{thm:dihtype}, \ref{thm:res} and \ref{thm:parity}, with $\Dial=H^D-\Res$ in even degree.
\end{proof}

Numerically: $\Dial(4)\approx0.3932$, $\Dial(6)\approx0.3637$, $\Ipair=0.4739,\,1.25,\,0.2027,\,1.4739$ for $n=3,4,5,6$.

\section{Cyclic laws}\label{sec:cyclic}

\begin{theorem}[Root-count law]\label{thm:rootcount}
For every $n\ge1$, $R^C(n)=\pi(n)$.
\end{theorem}
\begin{proof}
$T(a)=1$ iff $a=0$, so $R$ pins $0$ and is constant elsewhere. Apply Lemma~\ref{lem:pinned}.
\end{proof}

\begin{proposition}[Totient form]\label{prop:totient}
$H^C(n)=\log_2n-\frac1n\sum_{d\mid n}\varphi(d)\log_2\varphi(d)$.
\end{proposition}
\begin{proof}
The fibre of $T$ over $d\mid n$ has $\varphi(d)$ elements.
\end{proof}

\begin{theorem}[Prime losslessness]\label{thm:prime}
For $n\ge2$, $R^C(n)=H^C(n)$ iff $n$ is prime; for composite $n$, $R^C(n)<H^C(n)$.
\end{theorem}
\begin{proof}[Proof sketch]
For $n$ prime, $T\in\{1,n\}$ and $R$ recodes $T$ injectively. For composite $n$ we need $\sum_{d\mid n,d>1}\varphi(d)\log_2\varphi(d)<(n-1)\log_2(n-1)$. The weights sum to $n-1$, each $\varphi(d)\le n-1$, and at the least prime factor $q<n$ we have $\varphi(q)=q-1<n-1$, so the inequality is strict.
\end{proof}

\section{Dihedral laws}\label{sec:dihedral}

\begin{lemma}\label{lem:fix}
For $n\ge3$: $T(r_0)=n$ and $T(r_i)=0$ for $i\neq0$. If $n$ is odd then $T(s_i)=1$. If $n$ is even then $T(s_i)=2$ for even $i$ and $0$ for odd $i$.
\end{lemma}
\begin{proof}
$s_i(v)=v$ iff $2v=i$ in $\Z/n$.
\end{proof}

Hence the type distributions on $2n$ elements are $\{0:n-1,\,1:n,\,n:1\}$ for odd $n$ and $\{0:\frac{3n}2-1,\,2:\frac n2,\,n:1\}$ for even $n\ge4$.

\begin{theorem}[Dihedral type law]\label{thm:dihtype}
For odd $n\ge3$, $H^D(n)=1+\frac12\pi(n)$. For $n=2m$ with $m\ge2$,
\[
H^D(n)=\log_2(4m)-\frac{(3m-1)\log_2(3m-1)+m\log_2m}{4m}.
\]
\end{theorem}
\begin{proof}
Insert the distributions into the definition. For odd $n$, $\log_2(2n)-\frac{(n-1)\log_2(n-1)+n\log_2n}{2n}=1+\frac12\pi(n)$.
\end{proof}

\begin{theorem}[Bridge]\label{thm:bridge}
On the rotation fibre $\mathcal R=\rho^{-1}(0)$, $H_{\mathcal R}(T)=\pi(n)=R^C(n)$.
\end{theorem}
\begin{proof}
$T$ pins $r_0$ on $\mathcal R$. Apply Lemma~\ref{lem:pinned} and Theorem~\ref{thm:rootcount}.
\end{proof}

On the reflection fibre $\mathcal S$, $H_{\mathcal S}(T)=0$ for odd $n$ and $=1$ for even $n$. Since $\rho$ is a fair coin, $\Res(n)=\frac12H_{\mathcal R}(T)+\frac12H_{\mathcal S}(T)$.

\begin{theorem}[Residue law]\label{thm:res}
For $n\ge3$, $\Res(n)=\frac12\pi(n)$ if $n$ is odd and $\Res(n)=\frac12\pi(n)+\frac12$ if $n$ is even.
\end{theorem}

\section{The parity law}\label{sec:parity}

\begin{theorem}[Odd one-bit law]\label{thm:odd}
For odd $n\ge3$, $\Dial(n)=1$.
\end{theorem}
\begin{proof}
Either subtract Theorem~\ref{thm:res} from Theorem~\ref{thm:dihtype}, or argue conceptually: $\rho(g)=1\iff T(g)=1$ (no rotation fixes exactly one vertex), so $\rho$ is a function of $T$, and Theorem~\ref{thm:chain} gives $I(T;\rho)=H(\rho)=1$.
\end{proof}

\begin{proposition}\label{prop:even}
For even $n\ge4$, $\Dial(n)<1$.
\end{proposition}
\begin{proof}
By Theorem~\ref{thm:symm}, $\Dial(n)=1-H(\rho\mid T)$. The elements $r_1$ and $s_1$ both have $T=0$ but different $\rho$, so $H(\rho\mid T)>0$ by Lemma~\ref{lem:pos}.
\end{proof}

\begin{theorem}[Parity law]\label{thm:parity}
For $n\ge3$: $I_{D_n}(T;\rho)=1$ if and only if $n$ is odd.
\end{theorem}

\begin{remark}
At $n=2$ the identity and the reflections have equal fixed-point counts, so the dihedral laws need $n\ge3$.
\end{remark}

\section{Verdicts and asymptotics}

\begin{corollary}[Verdicts]
(1) $R^C=H^C$ at $n=3,5$, and $R^C<H^C$ at $n=4,6$. (2) $\Ipair(3),\Ipair(5)<1<\Ipair(4),\Ipair(6)$. (3) $\Dial=1$ at $n=3,5$, $\Dial<1$ at $n=4,6$, and $\Res>0$ at all four. (4) $R^C(n)<H^D(n)$ for $n=3,\dots,6$.
\end{corollary}
\begin{proof}
Theorems~\ref{thm:prime} and \ref{thm:parity}, plus the bounds $1.58<L<1.59$ and $2.32<L_5<2.33$.
\end{proof}

\begin{theorem}[Pinning bounds]
For $n\ge2$, $0<\pi(n)\le\frac1{\ln2}\bigl(\frac1{n-1}+\frac{\ln(n-1)}n\bigr)$. Hence $\pi(n)\to0$.
\end{theorem}
\begin{proof}[Proof sketch]
$\pi(n)\ln2=(\ln n-\ln(n-1))+\frac1n\ln(n-1)$, and $\ln\frac n{n-1}\le\frac1{n-1}$.
\end{proof}

\begin{theorem}[Abelian saturation]
Along odd $n$, $\Dial(n)/H^D(n)=1/(1+\frac12\pi(n))\to1$, while $\Res(n)=\frac12\pi(n)>0$ for every odd $n\ge3$.
\end{theorem}

Sample abelian shares: $0.685$ ($n=3$), $0.961$ ($n=101$), $0.99926$ ($n=10001$).

\section{Cross-check and algorithms}

The values previously obtained by enumeration, namely $R^C(4)=2-\frac34L$, $R^C(6)=1+L-\frac56L_5$, $H^D(6)=\frac34L$ and $\Res(6)=1+\frac L2-\frac5{12}L_5$, are reproduced by Theorems~\ref{thm:rootcount}, \ref{thm:dihtype} and \ref{thm:res}.

\begin{algorithm}[Fibre counting]
Enumerate $G$. Tabulate the value counts of $g$, and within each dial fibre the counts of $g$. Return $H$, $H(g\mid k)$ and $I$. The cost is $O(|G|)$ read-out evaluations, $O(n^2)$ for $D_n$ with naive fixed-point counting, and $O(n)$ using Lemma~\ref{lem:fix}.
\end{algorithm}

\begin{algorithm}[Closed forms]
Compute $\pi(n)$, then apply Theorems~\ref{thm:rootcount}--\ref{thm:parity}. This takes $O(1)$ arithmetic per degree.
\end{algorithm}

\section{Discussion and future work}

``Complete'' means: every degree-$3$-to-$6$ cyclic and dihedral entry is a closed form, every cyclic root-count and dihedral column is an instance of an all-degree law, and the laws recover the enumerated values. Other Galois groups of degrees $4$ to $6$ ($A_4$, $S_4$, $F_{20}$, $A_5$, $S_5$, \dots) are not covered.

Arithmetically, for $x^n-a$ with $n$ odd, a prime is a reflection prime exactly when $x^n-a$ has exactly one root modulo $p$. For $x^3-2$, every $p\equiv2\pmod3$ gives one root, while $p\equiv1\pmod3$ gives $0$ or $3$.

\begin{enumerate}
\item \emph{Even-degree dial limit.} Conjecture: $\Dial(2m)$ decreases strictly to $h(1/4)-\frac12\approx0.3113$. Numerically $\Dial(400)\approx0.3120$.
\item \emph{Full abelianisation of $D_{2m}$.} Expected: $I=H^D(2m)-\pi(m)/4$.
\item \emph{Other groups.} The pinning, chain-rule and fibre lemmas apply to any finite permutation group.
\item \emph{Pair channel.} Find closed forms of $\Ipair(n)$ for all $n$ and explain the binary cap.
\end{enumerate}

