from __future__ import annotations
from collections import Counter, defaultdict
from math import log2
from typing import Callable, Hashable, Iterable, List, Tuple, TypeVar

G = TypeVar("G")


def counting_entropy(values: Iterable[Hashable]) -> float:
    """H = log2|s| - (1/|s|) sum_a log2 |fibre(a)|, i.e. Shannon entropy of the push-forward."""
    c = Counter(values)
    n = sum(c.values())
    return -sum(k / n * log2(k / n) for k in c.values())


def channel(group: List[G], readout: Callable[[G], Hashable],
            dial: Callable[[G], Hashable]) -> Tuple[float, float, float]:
    """Return (H(T), H(T | dial), I(dial ; T)) for a uniformly random group element."""
    h = counting_entropy(readout(x) for x in group)
    fibres: dict = defaultdict(list)
    for x in group:
        fibres[dial(x)].append(readout(x))
    cond = sum(len(f) / len(group) * counting_entropy(f) for f in fibres.values())
    return h, cond, h - cond


def dihedral(n: int) -> List[Tuple[str, int]]:
    return [("r", i) for i in range(n)] + [("s", i) for i in range(n)]


def fix_count(n: int) -> Callable[[Tuple[str, int]], int]:
    def T(g: Tuple[str, int]) -> int:
        k, i = g
        if k == "r":
            return n if i == 0 else 0
        if n % 2:
            return 1
        return 2 if i % 2 == 0 else 0
    return T


if __name__ == "__main__":
    for n in range(3, 11):
        h, c, i = channel(dihedral(n), fix_count(n), lambda g: g[0])
        print(f"D_{n}: H(T)={h:.6f}  H(T|rot)={c:.6f}  I(rot;T)={i:.6f}")

from __future__ import annotations
from math import gcd, log2
from typing import Dict


def pin_ent(n: int) -> float:
    """Pinning entropy pi(n) = h(1/n)."""
    return 0.0 if n <= 1 else log2(n) - (n - 1) / n * log2(n - 1)


def totient(d: int) -> int:
    return sum(1 for k in range(1, d + 1) if gcd(k, d) == 1)


def master_row(n: int) -> Dict[str, float]:
    """Closed-form evaluation of the cyclic and dihedral columns at degree n >= 3."""
    divisors = [d for d in range(1, n + 1) if n % d == 0]
    cyc_type = log2(n) - sum(totient(d) * log2(totient(d)) for d in divisors) / n
    root_count = pin_ent(n)                       # root-count law
    if n % 2:                                     # odd dihedral laws
        dih_type = 1 + pin_ent(n) / 2
        residue = pin_ent(n) / 2
    else:                                         # even dihedral laws
        m = n // 2
        dih_type = log2(4 * m) - ((3 * m - 1) * log2(3 * m - 1) + m * log2(m)) / (4 * m)
        residue = pin_ent(n) / 2 + 0.5
    return {"H_cyc(T)": cyc_type, "H(#roots)": root_count,
            "lossless": float(abs(cyc_type - root_count) < 1e-12),
            "H_dih(T)": dih_type, "H(T|rot)": residue, "I(rot;T)": dih_type - residue}


if __name__ == "__main__":
    for n in (3, 4, 5, 6, 7, 8, 9, 10):
        print(n, {k: round(v, 6) for k, v in master_row(n).items()})

